using System;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SpicyLollipopOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/SpicyLollipopOmenData")]
public class SpicyLollipopOmenData : OmenData
{
	[NonSerialized]
	private OmenInstance omenInstance;

	public override void Initialize(OmenInstance omenInstance)
	{
		this.omenInstance = omenInstance;
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartStartTurnOmens.Add(omenInstance);
		ReferenceSingleton<MiscOmensHandler>.Instance.SpicyLollipopOmenAction = delegate
		{
			if (!AlreadyUsed && ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Count == 0 && (BattleAction as DrawAction).CheckConditionToBeCasted(playerHand: false, DiceOwnerEnum.PLAYER))
			{
				omenInstance.ActivateOmenFeedback();
				ActivateOmen();
				AlreadyUsed = true;
				return true;
			}
			return false;
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartStartTurnOmens.Remove(omenInstance);
		ReferenceSingleton<MiscOmensHandler>.Instance.SpicyLollipopOmenAction = null;
	}
}
